(51, 'Meat Lovers Omelette', 'Grilled prime rib, crumbled chorizo sausage, bacon, fire-roasted bell peppers and onions, and Cheddar cheese covered with Pepper Jack queso. Served with hash browns and choice of bread.', '12.59', 1, 13, 0),
(52, 'Philly Cheesesteak Omelette', 'Grilled prime rib, crumbled chorizo sausage, bacon, fire-roasted bell peppers and onions, and Cheddar cheese covered with Pepper Jack queso. Served with hash browns and choice of bread.', '12.35', 1, 13, 0),
(53, 'Ultimate Omelette', 'Crumbled sausage, bacon, fire-roasted bell peppers and onions, mushrooms, diced tomatoes and shredded Cheddar cheese. Served with hash browns and choice of bread.', '12.35', 1, 13, 0),
(54, 'Lumberjack Slam', 'Two buttermilk pancakes, a slice of grilled ham, two bacon strips, two sausage links and two eggs, plus hash browns and choice of bread.', '12.83', 1, 13, 0),
(55, 'All American Slam', 'Three scrambled eggs with Cheddar cheese, two bacon strips and two sausage links, plus hash browns and choice of bread.', '12.83', 1, 13, 0),
(56, 'French Toast Slam', 'Two thick slices of our fabulous French toast with two eggs, two bacon strips and two sausage links.', '10.79', 1, 13, 0),
(57, 'Country Fried Steak & Eggs', 'A golden-fried chopped beef steak smothered in rich country gravy. Served with two eggs, hash browns and choice of bread.', '13.07', 1, 13, 0),
(58, 'T-Bone Steak and Eggs', '"A tender 13 oz. seasoned T-Bone steak served with two eggs, hash browns and choice of bread"', '18.71', 1, 13, 0),
(59, 'Moon Over My Hammy', 'Our classic ham and scrambled egg sandwich with Swiss and American cheeses on grilled sourdough. Served with hash browns.', '10.79', 1, 13, 0),
(60, 'The Grand Slamwich', 'Two scrambled eggs, crumbled sausage, bacon, shaved ham and American cheese on potato bread grilled with a maple spice spread. Served with hash browns.', '11.15', 1, 13, 0),
(61, 'Build your own Sampler', 'Pick three and make it your own. Served with your choice of dipping sauces. Jalapeño Bottle Caps®, Mozzarella Cheese Sticks, Onion Rings, Cheese Quesadilla, Chips & Queso and Chicken Strips. \n3 items', '10.79', 1, 14, 0),
(62, 'Build your own Sampler', 'Pick three and make it your own. Served with your choice of dipping sauces. Jalapeño Bottle Caps®, Mozzarella Cheese Sticks, Onion Rings, Cheese Quesadilla, Chips & Queso and Chicken Strips. \n2 items', '7.55', 1, 14, 0),
(63, 'Pancake Puppies', '"Delicious bite-sized round pancakes rolled in cinnamon sugar and served with warm syrup"\n10 Puppies', '3.59', 1, 14, 0),
(64, 'Pancake Puppies', '"Delicious bite-sized round pancakes rolled in cinnamon sugar and served with warm syrup"\n2 Puppies', '2.39', 1, 14, 0),
(65, 'Chicken Stripes', 'Spicy, golden brown breaded chicken strips tossed in your choice of Sweet & Tangy BBQ or Buffalo sauce. Served with celery sticks and your choice of dipping sauce.', '9.47', 1, 14, 0),
(66, 'Zesty Nachos', 'Our tortilla chips are cooked fresh to order. Topped with Pepper Jack queso, shredded Cheddar cheese, seasoned nacho meat, freshly made pico de gallo and sour cream. Nachos also available in a half size portion.', '10.79', 1, 14, 0),
(67, 'Mozzarella Chease Sticks', 'Golden fried with a side of dipping sauce.', '7.55', 1, 14, 0),
(68, 'Smothered Cheese Fries', 'Wavy-cut French fries covered with Pepper Jack queso, shredded Cheddar cheese and crumbled bacon. Served with a side of creamy ranch dressing.', '7.19', 1, 14, 0),
(69, 'Chicken Bacon Classic', 'A grilled seasoned chicken breast topped with melted Swiss Cheese, bacon and a creamy pepper sauce. Served with lettuce, tomato, red onions and pickles. Served with your choice of wavy-cut French fries, hash browns, seasonal fruit or dippable veggies.', '11.27', 1, 15, 0),
(70, 'Chicken Salad Sandwich', 'Homemade with roasted seasoned chicken, celery, red grapes, toasted almonds and mayo. Served with spring mix and tomato on toasted 7-grain bread. Served with your choice of wavy-cut French fries, hash browns, seasonal fruit or dippable veggies.', '10.79', 1, 15, 0),
(71, 'Club Sandwich', 'Thinly sliced turkey breast, crisp bacon, lettuce, tomato and mayo on toasted 7-grain bread. Served with your choice of wavy-cut French fries, hash browns, seasonal fruit or dippable veggies.', '12.35', 1, 15, 0),
(72, 'Chicken Avocado Sandwich', 'A grilled seasoned chicken breast with fresh avocado, pico de gallo, lettuce and sour cream on a whole wheat bun. Served with Fit Fare® fresh veggies as your side choice. Fit Fare® Light: Under 550 calories. Fit Fare® Protein: Over 20g of protein.', '10.79', 1, 15, 0),
(73, 'Prime Rib Philly Melt', 'Juicy prime rib, mushrooms and onions sautéed, then topped with melted Swiss cheese on grilled garlic and herb ciab', '11.75', 1, 15, 0),
(74, 'The Super Bird', 'Thinly sliced turkey breast with melted Swiss cheese, crisp bacon and tomato on grilled sourdough. Served with your choice of wavy-cut French fries, hash browns, seasonal fruit or dippable veggies.', '10.77', 1, 15, 0),
(75, 'Bourbon Bacon Burger', 'A hand-pressed beef patty topped with Cheddar cheese, bacon, sautéed onions and mushrooms. Served on a Cheddar bun with lettuce, tomato, red onions, pickles and a sweet bourbon sauce. Served with your choice of wavy-cut French fries, hash browns, seasonal ', '11.99', 1, 15, 0),
(76, 'Bacon Avocado Cheese Burger', 'Crispy bacon, fresh avocado and melted Cheddar cheese top a hand-pressed beef patty. Served with mayo, lettuce, tomato, red onions and pickles. Served with your choice of wavy-cut French fries, hash browns, seasonal fruit or dippable veggies.', '11.99', 1, 15, 0),
(77, 'Mushroom Swiss Burger', 'Melted Swiss cheese and mushrooms sautéed in garlic and herbs top a hand-pressed beef patty. Served with lettuce, tomato, red onions and pickles. Served with your choice of wavy-cut French fries, hash browns, seasonal fruit or dippable veggies.', '11.75', 1, 15, 0),
(78, 'Prime Rib Cobb Salad', 'Tender prime rib, bacon, fresh avocado, grape tomatoes, Cheddar cheese, hard-boiled egg and potato sticks atop a bed of spring mix. Served with the dressing of your choice. Also available: Grilled Chicken Cobb Salad or Fried Chicken Strips Cobb Salad.', '11.75', 1, 16, 0),
(79, 'Cranberry Apple Chicken Salad', 'Grilled seasoned chicken breast, glazed pecans, apple slices and dried cranberries atop a bed of spring mix. Served with balsamic vinaigrette. This salad is also available in a half size portion. Fit Fare® Lean: Under 15g of fat Fit Fare® Light: Under 550 ', '11.75', 1, 16, 0),
(80, 'Brooklyn Spaghetti & Meatballs', 'Three seasoned meatballs atop a bed of pasta covered in a rich, meaty tomato sauce. Served with a side of shredded Italian cheeses and garlic toast.', '12.35', 1, 17, 0),
(81, 'T-Bone Steak', 'A tender 13 oz. seasoned T-Bone steak with your choice of two sides and dinner bread.', '19.19', 1, 17, 0),
(82, 'Sirloin Steak', 'A USDA select, 8 oz. seasoned sirloin steak cooked to perfection. Served with your choice of two sides and dinner bread. Fit Fare® Lean: Under 15g of fat when you choose whole grain rice, steamed zucchini & squash and without dinner bread. Fit Fare® Protei', '14.15', 1, 17, 0),
(83, 'Slow Cooked Pot Roast', 'Our slow-cooked pot roast, creamy mashed potatoes and herb-roasted carrots, celery, mushrooms and onions atop grilled ciabatta bread and covered in rich gravy.', '12.71', 1, 17, 0),
(84, 'Country Fried Steak', 'A dinner-sized, golden-fried chopped beef steak smothered in rich country gravy. Served with your choice of two sides and dinner bread.', '14.75', 1, 17, 0),
(85, 'Chicken Strips', 'Four Spicy, golden-brown breaded chicken strips served with a dipping sauce, your choice of two sides and dinner bread.', '13.19', 1, 17, 0),
